+    src.count = count;
+    src.id = id;
+    src.type = type;
+    src.ifd_lead = (uint8_t *) ifd_lead;
+    src.ifd_offset = ifd_offset;
+    if (type == AV_TIFF_IFD)
+        src.value.ifd = * (const AVExifMetadata *) value;
+    else
+        src.value.ptr = (void *) value;
