+void av_exif_free(AVExifMetadata *ifd)
+{
+    if (!ifd)
+        return;
+    if (!ifd->entries) {
+        ifd->count = 0;
+        ifd->size = 0;
+        return;
+    }
+    for (size_t i = 0; i < ifd->count; i++) {
+        AVExifEntry *entry = &ifd->entries[i];
+        exif_free_entry(entry);
+    }
+    av_freep(&ifd->entries);
+    ifd->count = 0;
+    ifd->size = 0;
+}
