+    ret->count = ifd->count;
+    if (ret->count) {
+        size_t required_size;
+        if (av_size_mult(ret->count, sizeof(*ret->entries), &required_size) < 0)
+            goto fail;
+        ret->entries = av_fast_realloc(NULL, &ret->size, required_size);
+        if (!ret->entries)
