+    bytestream2_skip(&gb_hdr, 4);
+    bytestream2_skip(&gb_hdr, 4 * 3 * 3);
+    bytestream2_skip(&gb_hdr, 4);
+    bytestream2_skip(&gb_hdr, 2);
