        av_tree_insert(&s->root, nodes[i], cmp_insert, &tnode);
        nodes[i]->poc -= dec;
        r = av_tree_insert(&s->root, nodes[i], cmp_insert, &tnode);
        if (r && r != nodes[i]) {
            *r = *nodes[i];
