+}
+
 static int decode_usac_core_coder(AACDecContext *ac, AACUSACConfig *usac,
                                   AACUsacElemConfig *ec, ChannelElement *che,
                                   GetBitContext *gb, int indep_flag, int nb_channels)
 {
     int ret;
     int arith_reset_flag;
     AACUsacStereo *us = &che->us;
