+        skip_bits_long(gb, 1 + rice_order + q);
+        return (q << rice_order) +
+                (((b << (q + 1)) >> 1) >> (31 - rice_order));
+    }
+
+    bits = exp_order + (q << 1) - switch_bits;
+    skip_bits_long(gb, bits);
+    return (b >> (32 - bits)) +
+           ((switch_bits + 1) << rice_order) -
