+                       (nb_time_slots - 1);
+
+    /* CLD */
+    err = ff_aac_ec_data_dec(gb, &mps->ott[MPS_CLD], MPS_CLD,
+                             0, 0, nb_bands,
+                             indep, indep, mps->nb_param_sets);
+    if (err < 0) {
