+            int tmp[MPS_MAX_PARAM_BANDS + 1];
+            create_mapping(tmp, start_band, stop_band, stride);
+            map_freq(tmp_idx_data[parmSlot], ld->data[set_idx],
+                     tmp, dataBands);
