+            x1 = param_set_idx[i1];
+            xi = param_set_idx[i];
+            x2 = param_set_idx[i2];
+
+            for (int band = start_band; band < stop_band; band++) {
+                int yi, y1, y2;
+                y1 = tmp_idx_data[i1][band];
+                y2 = tmp_idx_data[i2][band];
+                if (x1 != x2) {
+                    yi = y1 + (xi - x1) * (y2 - y1) / (x2 - x1);
+                } else {
