+  static FT_Bool
+  tt_face_validate_coverage( FT_Byte*  table,
+                             FT_Byte*  table_limit,
+                             FT_UInt   max_num_coverage_indices )
+  {
+    FT_UInt  format;
+
+    FT_Byte*  p = table;
+    FT_Byte*  limit;
+
+    FT_Long  last_id = -1;
