+    if ( gpos_length < 10 )
+      goto Fail;
+
+    gpos_limit = gpos + gpos_length;
+
+    /* We first need the number of GPOS lookups. */
+    lookupListOffset = FT_PEEK_USHORT( gpos + 8 );
