   tt_face_done_gpos( TT_Face  face )
   {
+    FT_Stream  stream = face->root.stream;
+    FT_Memory  memory = face->root.memory;
+
+
+    FT_FRAME_RELEASE( face->gpos_table );
+    FT_FREE( face->gpos_lookups_kerning );
