diff --git a/apps/crl2pkcs7.c b/apps/crl2pkcs7.c
index 681c60285f..ba24d31d5f 100644
--- a/apps/crl2pkcs7.c
+++ b/apps/crl2pkcs7.c
@@ -209,21 +209,24 @@ static int add_certs_from_file(STACK_OF(X509) *stack, char *certfile)
     sk = PEM_X509_INFO_read_bio(in, NULL, NULL, NULL);
     if (sk == NULL) {
         BIO_printf(bio_err, "error reading the file, %s\n", certfile);
         goto end;
     }

     /* scan over it and pull out the CRL's */
     while (sk_X509_INFO_num(sk)) {
         xi = sk_X509_INFO_shift(sk);
         if (xi->x509 != NULL) {
-            sk_X509_push(stack, xi->x509);
+            if (!sk_X509_push(stack, xi->x509)) {
+                X509_INFO_free(xi);
+                goto end;
+            }
             xi->x509 = NULL;
             count++;
         }
         X509_INFO_free(xi);
     }

     ret = count;
  end:
     /* never need to OPENSSL_free x */
     BIO_free(in);

