+        if (BIO_puts(out, "\n") <= 0)
+            return 0;
+        return 1;
+    case (OSSL_INFO_SYNTAX_TYPE_POINTER):
+        if (BIO_printf(out, "%*sPointer:\n", indent, "") <= 0)
+            return 0;
+        return i2r_INFO_SYNTAX_POINTER(method, info->choice.pointer, out, indent + 4);
+    default:
+        return 0;
+    }
+    return 0;
+}
