+    /* DTLS 1.2 Session ID: [SH][CCS][Fin] -> [CCS][SH][Fin] */
+    { 0, SSL3_MT_SERVER_HELLO, DTLS1_2_VERSION },
+    /* DTLS 1.2 Ticket renewal: [NST][CCS][Fin] -> [CCS][NST][Fin] */
+    { 1, SSL3_MT_NEWSESSION_TICKET, DTLS1_2_VERSION },
