+            &target_pkt, &target_rec))
+        || !TEST_int_eq(ccs_pkt + 1, target_pkt)
+        || !TEST_int_eq(ccs_rec, 0)
+        || !TEST_int_eq(target_rec, 0))
+        return 0;
+
+    return 1;
