+    if (!TEST_int_gt(ret, 0)) {
+        TEST_info("SSL_accept: ret=%d err=%d state=%s",
+            ret, SSL_get_error(sssl, ret),
+            SSL_state_string_long(sssl));
+        goto end;
+    }
