+  rc = fts5HashEntrySort(pHash, &pList);
+  if( rc==SQLITE_OK ){
+    while( pList ){
+      Fts5HashEntry *pNext = pList->pNext;
+      if( rc==SQLITE_OK ){
+        u8 *pPtr = (u8*)pList;
+        int nKey = strlen(pList->zKey);
+        int iOff = pList->iRowidOff;
+        int iEnd = sizeof(Fts5HashEntry) + nKey + 1;
+        int nByte = pList->nData - pList->iRowidOff;
