+        out << (type.kind() == kRef ? "(ref " : "(ref null ");
+        if (type.has_index()) {
+          PrintTypeName(out, type.ref_index());
+        } else {
+          out << type.name();
+        }
+        out << ')';
+      } else {
+        out << type.name();
+      }
+      break;
+    case kRtt:
+      out << "(rtt ";
+      PrintTypeName(out, type.ref_index());
+      out << ')';
+      break;
+    default:
