+  if (alphabet == simdutf::base64_options::base64_default &&
+      omit_padding == true) {
+    alphabet = simdutf::base64_options::base64_default_no_padding;
+  } else if (alphabet == simdutf::base64_options::base64_url &&
+             omit_padding == false) {
