+        GetSimdOpcodeName(graph_.Get(node_group[0])).c_str(),
+        node_group[0].id(), node_group[1].id());
+  PackNode* intersect_pnode = phase_zone_->New<PackNode>(
+      phase_zone_, node_group, PackNode::kIntersectPackNode);
