   block->set_deferred(true);
   block->RemovePredecessorFollowing(control);
   ReduceResult result = reducer_.AddNewControlNode<Deopt>({}, reason);
   CHECK(!result.IsDoneWithAbort());
   return ReduceResult::DoneWithAbort();
 }
