+            .get_defined_memory(wasmtime_export.index)
+            .as_mut()
+            .unwrap();
+        let shared_memory = memory
+            .as_shared_memory()
+            .expect("unable to convert from a shared memory");
+        Self(shared_memory, store.engine().clone())
+    }
