+        let mut owned = String::new();
+        owned.reserve_exact(s.len())?;
+        owned.push_str(s).expect("reserved capacity");
+        let owned = owned
+            .into_boxed_str()
+            .expect("reserved exact capacity, so shouldn't need to realloc");
