+// allow it for `OpaqueRootScope` because it is only Wasmtime-internal and not
+// publicly exported.
+impl DerefMut for OpaqueRootScope<'_> {
+    fn deref_mut(&mut self) -> &mut Self::Target {
+        self.store
+    }
